{
  "name": "writ-zapier",
  "version": "0.1.0",
  "description": "Writ on Zapier: scrape and map pages, crawl sites, run Writ workflows and monitors, and start Zaps from Writ events.",
  "private": true,
  "license": "MIT",
  "author": "The Writ Project Authors",
  "homepage": "https://github.com/usewrit/writ-integrations/tree/main/zapier#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/usewrit/writ-integrations.git",
    "directory": "zapier"
  },
  "main": "index.js",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "test": "vitest run",
    "validate": "zapier-platform validate"
  },
  "dependencies": {
    "zapier-platform-core": "19.3.0"
  },
  "devDependencies": {
    "zapier-platform-cli": "19.3.0",
    "vitest": "^3.2.4"
  }
}

'use strict';

const { SCOPES, url } = require('./lib/config');

/**
 * OAuth 2.0 against Writ's own authorization server (authorization code with PKCE,
 * refresh tokens). Writ registers the Zapier client; its id and secret are the
 * CLIENT_ID / CLIENT_SECRET environment variables of the Zapier app.
 */
module.exports = {
  type: 'oauth2',
  oauth2Config: {
    authorizeUrl: {
      url: url('/api/oauth/authorize'),
      params: {
        client_id: '{{process.env.CLIENT_ID}}',
        state: '{{bundle.inputData.state}}',
        redirect_uri: '{{bundle.inputData.redirect_uri}}',
        response_type: 'code',
        scope: SCOPES.join(' '),
      },
    },
    getAccessToken: {
      url: url('/api/oauth/token'),
      method: 'POST',
      body: {
        code: '{{bundle.inputData.code}}',
        client_id: '{{process.env.CLIENT_ID}}',
        client_secret: '[REDACTED]}}',
        redirect_uri: '{{bundle.inputData.redirect_uri}}',
        code_verifier: '{{bundle.inputData.code_verifier}}',
        grant_type: 'authorization_code',
      },
      headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' },
    },
    refreshAccessToken: {
      url: url('/api/oauth/token'),
      method: 'POST',
      body: {
        refresh_token: '[REDACTED]}}',
        client_id: '{{process.env.CLIENT_ID}}',
        client_secret: '[REDACTED]}}',
        grant_type: 'refresh_token',
      },
      headers: { 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' },
    },
    scope: SCOPES.join(' '),
    autoRefresh: true,
    enablePkce: true,
  },
  test: { url: url('/api/auth/me') },
  connectionLabel: '{{email}}',
};

import { describe, expect, it } from 'vitest';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const { signPayload, verifyWritSignature } = require('../lib/signature');
const { describeWritError } = require('../lib/errors');
const n = require('../lib/normalize');
const delivery = require('./signed-delivery.json');

const now = Number(delivery.timestamp) + 30;
const zapierHeaders = (signature, timestamp) => ({ 'Http-X-Writ-Signature-V1': signature, 'Http-X-Writ-Timestamp': timestamp });

describe('signature', () => {
  it('verifies a delivery Writ signed, with Zapier-style header names', () => {
    expect(signPayload(delivery.secret, delivery.timestamp, delivery.raw_body)).toBe(delivery.signature_v1);
    expect(verifyWritSignature(delivery.secret, zapierHeaders(delivery.signature_v1, delivery.timestamp), delivery.raw_body, now)).toEqual({ ok: true });
  });
  it('refuses a wrong secret, a re-serialised body, a replayed or old timestamp, and missing headers', () => {
    const h = zapierHeaders(delivery.signature_v1, delivery.timestamp);
    expect(verifyWritSignature('nope', h, delivery.raw_body, now).reason).toBe('mismatch');
    expect(verifyWritSignature(delivery.secret, h, JSON.stringify(JSON.parse(delivery.raw_body)), now).reason).toBe('mismatch');
    const later = String(Number(delivery.timestamp) + 3600);
    expect(verifyWritSignature(delivery.secret, zapierHeaders(delivery.signature_v1, later), delivery.raw_body, Number(later)).reason).toBe('mismatch');
    expect(verifyWritSignature(delivery.secret, h, delivery.raw_body, Number(delivery.timestamp) + 3600).reason).toBe('expired');
    expect(verifyWritSignature(delivery.secret, {}, delivery.raw_body, now).reason).toBe('missing');
  });
});

describe('errors', () => {
  it('splits 402 into a plan ceiling and missing credits', () => {
    expect(describeWritError(402, { detail: { message: 'Limit', limit: 3 } }).message).toContain('limit of 3');
    expect(describeWritError(402, { detail: 'Insufficient credits' }).message).toContain('Not enough Writ credits');
  });
  it('maps 401 to reconnect and 429 to throttle', () => {
    expect(describeWritError(401, {}).kind).toBe('auth');
    expect(describeWritError(429, {}, 30)).toMatchObject({ kind: 'throttle', retryAfter: 30 });
    expect(describeWritError(403, { detail: 'needs crawl:execute' }).message).toContain('crawl:execute');
  });
});

describe('normalize', () => {
  it('gives the change trigger one shape from a delivery and from the feed', () => {
    const hook = n.changeFromHook({
      event: 'change_detected', event_id: 'evt_1',
      target: { id: 4, url: 'https://e.com', name: 'E' },
      change: { id: 9, detected_at: '2026-11-19T00:00:00Z', content_before: 'a', content_after: 'b', content_truncated: true, full_content_after: 'bb', full_content_before: 'aa' },
    });
    expect(hook).toMatchObject({ id: 9, monitor_id: 4, content_before: 'aa', content_after: 'bb', content_truncated: false });
    const feed = n.changeFromFeed({ id: 9, target_id: 4, target_url: 'https://e.com', last_detected_at: '2026-11-19T00:00:00Z' });
    expect(Object.keys(feed).sort()).toEqual(Object.keys(hook).sort());
  });
  it('gives the run trigger one shape from a delivery and from a task', () => {
    const hook = n.runFromHook({ event: 'workflow_completed', event_id: 'evt_2', data: { workflow: { id: 3, name: 'W' }, run: { id: 7, status: 'success', success: true }, extracted_data: [{ a: 1 }] } });
    const task = n.runFromTask({ id: 7, workflow_id: 3, status: 'success', success: true, result_data: { extracted_data: [{ a: 1 }] } });
    expect(hook).toMatchObject({ id: 7, workflow_id: 3, success: true, extracted_data_json: '[{"a":1}]' });
    expect(Object.keys(task).sort()).toEqual(Object.keys(hook).sort());
  });
});

/**
 * The app against a real Writ server. Runs only with WRIT_E2E=1 and:
 *   WRIT_API_URL, CLIENT_ID, CLIENT_SECRET    the server and the Zapier OAuth app on it
 *   WRIT_TEST_AUTH_CODE, WRIT_TEST_CODE_VERIFIER, WRIT_TEST_REDIRECT_URI
 *                                             a fresh code the test user approved (PKCE)
 *   WRIT_TEST_API_KEY                         an API key of the same account, to look
 *                                             at its webhook subscriptions directly
 */
import { describe, expect, it } from 'vitest';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const live = process.env.WRIT_E2E === '1';

describe.runIf(live)('live against a Writ server', () => {
  const zapier = require('zapier-platform-core');
  const App = require('../index');
  const appTester = zapier.createAppTester(App);
  const { signPayload } = require('../lib/signature');
  const base = process.env.WRIT_API_URL;
  const authData = {};

  const withKey = (path, init = {}) =>
    fetch(`${base}${path}`, { ...init, headers: { Authorization: `Bearer ${process.env.WRIT_TEST_API_KEY}`, ...(init.headers || {}) } });

  it('exchanges the authorization code, refreshes, and tests the connection', async () => {
    const tokens = await appTester(App.authentication.oauth2Config.getAccessToken, {
      inputData: {
        code: process.env.WRIT_TEST_AUTH_CODE,
        code_verifier: process.env.WRIT_TEST_CODE_VERIFIER,
        redirect_uri: process.env.WRIT_TEST_REDIRECT_URI,
      },
    });
    expect(tokens.access_token).toMatch(/^wto_/);
    expect(tokens.refresh_token).toMatch(/^wtr_/);
    const refreshed = await appTester(App.authentication.oauth2Config.refreshAccessToken, { authData: tokens });
    expect(refreshed.access_token).not.toBe(tokens.access_token);
    Object.assign(authData, refreshed);
    const me = await appTester(App.authentication.test, { authData });
    expect(me.email).toBeTruthy();
  });

  it('runs every action and search', async () => {
    const page = await appTester(App.creates.scrape_page.operation.perform, { authData, inputData: { url: 'https://example.com', format: 'markdown' } });
    expect(page.title).toBe('Example Domain');
    const map = await appTester(App.creates.map_site.operation.perform, { authData, inputData: { url: 'https://example.com', limit: '5' } });
    expect(map.count).toBeGreaterThan(0);
    const monitor = await appTester(App.creates.create_monitor.operation.perform, { authData, inputData: { url: 'https://example.com/zapier-live', check_type: 'content' } });
    expect(monitor.id).toBeGreaterThan(0);
    const check = await appTester(App.creates.check_monitor.operation.perform, { authData, inputData: { monitor_id: monitor.id } });
    expect(check.monitor_id).toBe(monitor.id);
    const found = await appTester(App.searches.find_monitor.operation.perform, { authData, inputData: { query: 'zapier-live' } });
    expect(found.map((m) => m.id)).toContain(monitor.id);
    const crawl = await appTester(App.creates.start_crawl.operation.perform, { authData, inputData: { url: 'https://example.com', page_budget: '2' } });
    expect(crawl.id).toBeGreaterThan(0);
    const records = await appTester(App.searches.find_records.operation.perform, { authData, inputData: { workflow_id: crawl.data_workflow_id, query: 'x' } });
    expect(Array.isArray(records)).toBe(true);
    expect(Array.isArray(await appTester(App.searches.find_workflow.operation.perform, { authData, inputData: { name: 'a' } }))).toBe(true);
    for (const key of ['change_detected', 'workflow_completed', 'crawl_finished', 'monitor_health']) {
      expect(Array.isArray(await appTester(App.triggers[key].operation.performList, { authData, inputData: {} }))).toBe(true);
    }
    await expect(
      appTester(App.creates.run_workflow.operation.perform, { authData, inputData: { workflow_id: 99999999, wait: false } }),
    ).rejects.toThrow();
  });

  it('subscribes, receives a signed delivery, unsubscribes; a revoke removes what the app made', async () => {
    const targetUrl = 'https://hooks.zapier.com/hooks/standard/0/writ-live-test/';
    const sub = await appTester(App.triggers.workflow_completed.operation.performSubscribe, { authData, targetUrl, inputData: {}, meta: { zap: { id: 4242 } } });
    let rows = (await (await withKey('/api/webhooks/recipients')).json()).recipients;
    const row = rows.find((r) => r.id === sub.id);
    expect(row).toMatchObject({ integration: 'zapier', external_ref: '4242', created_via: 'oauth', event_types: ['workflow_completed'] });

    const payload = { event: 'workflow_completed', event_id: 'evt_live', data: { workflow: { id: 1, name: 'W' }, run: { id: 5, status: 'success', success: true } } };
    const content = JSON.stringify(payload);
    const timestamp = String(Math.floor(Date.now() / 1000));
    const items = await appTester(App.triggers.workflow_completed.operation.perform, {
      authData, inputData: {}, subscribeData: sub, cleanedRequest: payload,
      rawRequest: { content, headers: { 'Http-X-Writ-Timestamp': timestamp, 'Http-X-Writ-Signature-V1': signPayload(sub.secret, timestamp, content) } },
    });
    expect(items[0]).toMatchObject({ id: 5, success: true });

    await appTester(App.triggers.workflow_completed.operation.performUnsubscribe, { authData, subscribeData: sub });
    rows = (await (await withKey('/api/webhooks/recipients')).json()).recipients;
    expect(rows.find((r) => r.id === sub.id)).toBeUndefined();

    // A subscription left behind (a Zap deleted while Writ was unreachable) goes when
    // the person disconnects Zapier from Writ.
    const orphan = await appTester(App.triggers.crawl_finished.operation.performSubscribe, { authData, targetUrl, inputData: { outcome: 'both' } });
    const revoke = await fetch(`${base}/api/oauth/revoke`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ token: [REDACTED], token_type_hint: 'refresh_token', client_id: process.env.CLIENT_ID, client_secret: [REDACTED] }),
    });
    expect(revoke.status).toBe(200);
    rows = (await (await withKey('/api/webhooks/recipients')).json()).recipients;
    expect(rows.find((r) => r.id === orphan.id)).toBeUndefined();
    await expect(appTester(App.authentication.test, { authData })).rejects.toMatchObject({ name: 'RefreshAuthError' });
  });
});

/**
 * Every trigger, action and search against a stand-in Writ API on localhost, so the
 * suite runs anywhere (CI included). live.test.js runs the same app against a real
 * Writ server when WRIT_E2E=1.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createRequire } from 'module';
import http from 'http';

const require = createRequire(import.meta.url);
const { signPayload } = require('../lib/signature');

const calls = [];
let server;
let App;
let appTester;
let taskReads = 0;

const json = (res, status, body, headers = {}) => {
  res.writeHead(status, { 'content-type': 'application/json', ...headers });
  res.end(JSON.stringify(body));
};

function route(req, res, body) {
  const u = new URL(req.url, 'http://x');
  const key = `${req.method} ${u.pathname}`;
  calls.push({ key, query: Object.fromEntries(u.searchParams), body, headers: req.headers });
  switch (key) {
    case 'GET /api/auth/me': return json(res, 200, { email: 'person@example.com' });
    case 'GET /api/automation/workflows': return json(res, 200, [{ id: 1, name: 'HN front page' }, { id: 2, name: 'Harvest: x', workflow_type: 'crawl' }]);
    case 'GET /api/targets': return json(res, 200, [{ id: 4, url: 'https://example.com/pricing', name: 'Pricing' }, { id: 5, url: 'https://other.example' }]);
    case 'GET /api/targets/changes/recent': return json(res, 200, [
      { id: 91, target_id: 4, target_url: 'https://example.com/pricing', diff_snippet: '-49 +59', first_detected_at: '2026-11-19T10:00:00Z', last_detected_at: '2026-11-19T10:00:00Z' },
      { id: 92, target_id: 5, target_url: 'https://other.example', last_detected_at: '2026-11-19T09:00:00Z' },
    ]);
    case 'GET /api/automation/tasks': return json(res, 200, [
      { id: 7, workflow_id: 1, status: 'success', success: true, result_data: { extracted_data: [{ t: 1 }] } },
      { id: 8, workflow_id: 1, status: 'running' },
      { id: 9, workflow_id: 1, status: 'failed', success: false, error_message: 'Site refused' },
    ]);
    case 'GET /api/crawl': return json(res, 200, [{ id: 31, status: 'completed', name: 'c', workflow_id: 77 }, { id: 32, status: 'failed', error: 'x' }, { id: 33, status: 'running' }]);
    case 'POST /api/webhooks/recipients': return json(res, 200, { success: true, recipient: { id: 11, url: body.url } });
    case 'DELETE /api/webhooks/recipients/11': return json(res, 200, { success: true });
    case 'DELETE /api/webhooks/recipients/12': return json(res, 404, { detail: 'Webhook recipient not found' });
    case 'POST /api/crawl/scrape': return json(res, 200, { url: body.url, title: 'Example', format: body.format, markdown: '# Hi', engine: 'inline' });
    case 'POST /api/crawl/map': return json(res, 200, { urls: [{ url: body.url, title: 'Home', score: 1 }], count: 1 });
    case 'POST /api/crawl': return json(res, 200, { id: 40, name: 'Harvest', seed_url: body.url, status: 'queued', workflow_id: 78 });
    case 'POST /api/targets': return json(res, 201, { id: 6, url: body.url, checkType: body.check_type, enabled: true });
    case 'POST /api/targets/4/run': return json(res, 200, { ok: true, dispatched: 1 });
    case 'POST /api/automation/workflows/1/run': taskReads = 0; return json(res, 200, { task_id: 70, status: 'queued' });
    case 'GET /api/automation/tasks/70':
      taskReads += 1;
      return json(res, 200, taskReads < 2 ? { id: 70, status: 'running' } : { id: 70, workflow_id: 1, status: 'success', success: true, result_data: { extracted_data: [{ price: 59 }] } });
    case 'POST /api/automation/workflows/402/run': return json(res, 402, { detail: { message: 'Run limit reached', limit: 5 } });
    case 'POST /api/automation/workflows/403/run': return json(res, 402, { detail: 'Insufficient credits' });
    case 'POST /api/automation/workflows/401/run': return json(res, 401, { detail: 'Token revoked' });
    case 'POST /api/automation/workflows/429/run': return json(res, 429, { detail: 'Plan API rate limit exceeded' }, { 'retry-after': '42' });
    case 'GET /api/v1/workflows/1/data': return json(res, 200, { rows: [{ id: 'r1', title: 'Laptop', price: 999 }] });
    default: return json(res, 404, { detail: `no route ${key}` });
  }
}

beforeAll(async () => {
  server = http.createServer((req, res) => {
    let raw = '';
    req.on('data', (chunk) => { raw += chunk; });
    req.on('end', () => {
      let body = null;
      try { body = raw ? JSON.parse(raw) : null; } catch { body = raw; }
      route(req, res, body);
    });
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  process.env.WRIT_API_URL = `http://127.0.0.1:${server.address().port}`;
  process.env.CLIENT_ID = 'test-client';
  process.env.CLIENT_SECRET = 'test-secret';
  const zapier = require('zapier-platform-core');
  App = require('../index');
  appTester = zapier.createAppTester(App);
});

afterAll(() => new Promise((resolve) => server.close(resolve)));

const authData = { access_token: 'wto_test', refresh_token: 'wtr_test' };
const last = (key) => [...calls].reverse().find((call) => call.key === key);

describe('authentication', () => {
  it('tests the connection with /api/auth/me and labels it by email', async () => {
    const me = await appTester(App.authentication.test, { authData });
    expect(me.email).toBe('person@example.com');
    expect(last('GET /api/auth/me').headers.authorization).toBe('Bearer wto_test');
  });
  it('asks for the scopes Writ will show on its consent screen', () => {
    const scope = App.authentication.oauth2Config.authorizeUrl.params.scope;
    expect(scope).toContain('scrape:execute');
    expect(scope).toContain('triggers:delete');
    expect(App.authentication.oauth2Config.enablePkce).toBe(true);
  });
});

describe('hidden pickers', () => {
  it('lists workflows without crawl workflows, and monitors', async () => {
    expect(await appTester(App.triggers.workflow_list.operation.perform, { authData })).toEqual([{ id: 1, name: 'HN front page' }]);
    const monitors = await appTester(App.triggers.monitor_list.operation.perform, { authData });
    expect(monitors.map((m) => m.id)).toEqual([4, 5]);
  });
});

describe('REST hook triggers', () => {
  it('subscribes with a fresh secret, the event and the Zap id', async () => {
    const sub = await appTester(App.triggers.workflow_completed.operation.performSubscribe, {
      authData, targetUrl: 'https://hooks.zapier.com/hooks/standard/1/abc', inputData: {}, meta: { zap: { id: 555 } },
    });
    expect(sub.id).toBe(11);
    expect(sub.secret).toMatch(/^[0-9a-f]{64}$/);
    const sent = last('POST /api/webhooks/recipients');
    expect(sent.body).toMatchObject({
      url: 'https://hooks.zapier.com/hooks/standard/1/abc', event_types: ['workflow_completed'],
      integration: 'zapier', external_ref: '555', secret: sub.secret,
    });
    expect(sent.headers['idempotency-key']).toBeTruthy();
  });

  it('subscribes the crawl and monitor-status triggers to the chosen events', async () => {
    await appTester(App.triggers.crawl_finished.operation.performSubscribe, { authData, targetUrl: 'https://h/x', inputData: { outcome: 'both' } });
    expect(last('POST /api/webhooks/recipients').body.event_types).toEqual(['crawl_completed', 'crawl_failed']);
    await appTester(App.triggers.monitor_health.operation.performSubscribe, { authData, targetUrl: 'https://h/x', inputData: { events: ['monitor_stale'] } });
    expect(last('POST /api/webhooks/recipients').body.event_types).toEqual(['monitor_stale']);
    await appTester(App.triggers.change_detected.operation.performSubscribe, { authData, targetUrl: 'https://h/x', inputData: {} });
    expect(last('POST /api/webhooks/recipients').body.event_types).toEqual(['change_detected']);
  });

  it('unsubscribes, and an already removed subscription is not an error', async () => {
    await appTester(App.triggers.workflow_completed.operation.performUnsubscribe, { authData, subscribeData: { id: 11 } });
    expect(last('DELETE /api/webhooks/recipients/11')).toBeTruthy();
    await expect(appTester(App.triggers.workflow_completed.operation.performUnsubscribe, { authData, subscribeData: { id: 12 } })).resolves.toEqual({});
  });

  const deliver = (payload, secret, signWith = secret) => {
    const content = JSON.stringify(payload);
    const timestamp = String(Math.floor(Date.now() / 1000));
    return {
      authData,
      subscribeData: { id: 11, secret },
      cleanedRequest: payload,
      rawRequest: { content, headers: { 'Http-X-Writ-Timestamp': timestamp, 'Http-X-Writ-Signature-V1': signPayload(signWith, timestamp, content) } },
      inputData: {},
    };
  };

  it('emits a signed delivery and refuses a forged one', async () => {
    const payload = { event: 'workflow_completed', event_id: 'evt_9', data: { workflow: { id: 1, name: 'HN' }, run: { id: 70, status: 'success', success: true }, extracted_data: [{ a: 1 }] } };
    const items = await appTester(App.triggers.workflow_completed.operation.perform, deliver(payload, 's3cret'));
    expect(items).toEqual([expect.objectContaining({ id: 70, workflow_id: 1, success: true, extracted_data_json: '[{"a":1}]' })]);
    await expect(appTester(App.triggers.workflow_completed.operation.perform, deliver(payload, 's3cret', 'forged'))).rejects.toThrow(/did not sign/);
  });

  it('drops deliveries the Zap filtered out', async () => {
    const payload = { event: 'workflow_completed', event_id: 'evt_9', data: { workflow: { id: 2 }, run: { id: 71, status: 'failed', success: false } } };
    const bundle = deliver(payload, 's');
    bundle.inputData = { workflow_id: 1 };
    expect(await appTester(App.triggers.workflow_completed.operation.perform, bundle)).toEqual([]);
    bundle.inputData = { outcome: 'success' };
    expect(await appTester(App.triggers.workflow_completed.operation.perform, bundle)).toEqual([]);
    const other = deliver({ event: 'crawl_failed', data: {} }, 's');
    expect(await appTester(App.triggers.workflow_completed.operation.perform, other)).toEqual([]);
  });

  it('maps change and monitor-status deliveries', async () => {
    const change = await appTester(App.triggers.change_detected.operation.perform, deliver({
      event: 'change_detected', event_id: 'evt_c', target: { id: 4, url: 'https://example.com/pricing', name: 'Pricing' },
      change: { id: 91, content_before: 'a', content_after: 'b', content_truncated: false },
    }, 's'));
    expect(change[0]).toMatchObject({ id: 91, monitor_id: 4, content_after: 'b' });
    const health = await appTester(App.triggers.monitor_health.operation.perform, {
      ...deliver({ event: 'monitor_down', event_id: 'evt_h', data: { monitor: { id: 4, url: 'u' }, state: 'down', status_code: 503 } }, 's'),
      inputData: { events: ['monitor_down'] },
    });
    expect(health[0]).toMatchObject({ id: 'evt_h', state: 'down', status_code: 503 });
  });

  it('lists real data for samples, filtered like the hook', async () => {
    const changes = await appTester(App.triggers.change_detected.operation.performList, { authData, inputData: { monitor_id: 4 } });
